 var SunBlank = {

 	_templateParams:		{},

 	initOnDomReady: function()
 	{
		// Setup event to update submenu position
		(function($) {

			var RtlMenu = false;
			if($("body").hasClass("sunfw-direction-rtl"))
				RtlMenu = true;
			else {
				RtlMenu = false;
			}

			SunFwUtils.setSubmenuPosition(RtlMenu,$);

		})(jQuery);

        (function($) {
            $('.counting-up > span').addClass('counter');
            $('.counter').counterUp({
                delay: 10,
                time: 1000
            });
        })(jQuery);
        // Check megamenu is caret
        (function($) {

            if($('.sunfw-megamenu-sub-menu ul.nav li.parent').length) {

                $('.sunfw-megamenu-sub-menu ul.nav:not(.sub-menu) li.parent > a, .sunfw-megamenu-sub-menu ul.nav:not(.sub-menu) li.parent > span.nav-header').append('<span class="caret"></span>');

            }

        })(jQuery);
        // Fixed Menu Open Bootstrap
        (function($) {
            $('.sunfw-menu li.parent .caret').on("click", function(e){
                $(this).toggleClass('open');
                $(this).parent().next('ul').toggleClass('menuShow');
                e.stopPropagation();
                e.preventDefault();

            });

        })(jQuery);

		// Animation Menu when hover
		(function($) {
			var timer_out;
			timer_out = setTimeout(function() {
				$('.sunfwMenuSlide .dropdown-submenu, .sunfwMenuSlide .megamenu').hover(
					function() {
						$('.sunfw-megamenu-sub-menu, .dropdown-menu', this).stop( true, true ).slideDown('fast');
					},
					function() {
						$('.sunfw-megamenu-sub-menu, .dropdown-menu', this).stop( true, true ).slideUp('fast');
					}
					);

				$('.sunfwMenuFading .dropdown-submenu, .sunfwMenuFading .megamenu').hover(
					function() {
						$('.sunfw-megamenu-sub-menu, .dropdown-menu', this).stop( true, true ).fadeIn('fast');
					},
					function() {
						$('.sunfw-megamenu-sub-menu, .dropdown-menu', this).stop( true, true ).fadeOut('fast');
					}
					);
			}, 100);

		})(jQuery);

		(function($) {
			//Scroll Top
			if($('.sunfw-scrollup').length) {
				$(window).scroll(function() {
					if ($(this).scrollTop() > 350) {
						$('.sunfw-scrollup').fadeIn();
					} else {
						$('.sunfw-scrollup').fadeOut();
					}
				});

				$('.sunfw-scrollup').click(function(e) {
					e.preventDefault();
					$("html, body").animate({
						scrollTop: 0
					}, 600);
					return false;
				});
			}
			//Get BG Module Style SideMenu
			$('.menu-sidemenu').each(function(){
				var navbg = $(this).parents('[class*="module-style-"]').css("background-color");
				$(this).find('ul.nav-child').css('background-color',navbg);
			})

			//Accirdidon SideMenu at mobile device
			if ( jQuery(window).width() <= 768){
				jQuery('.menu-sidemenu li.parent > a').on('click', function(e){
					jQuery(this).toggleClass('active').next('ul').stop().slideToggle('medium');
					e.preventDefault();
				});
			}

	        // Artista
	        var centerLogo = '.sunfw-tpl-menu > li > a.jsn-center-logo';
	        if($(centerLogo).length) {
	        	$(centerLogo).closest('li').addClass('jsn-center-logo');
	        }


	        if($('.tab.tab-gallery').length){
	        	$('.tab.tab-gallery').after('<ul class="nav-tabs jsn-tabs"><li></li></ul>');
	        	$('.tab.tab-gallery a').click(function() {

	        		 $('ul.nav-tabs > li').trigger("click");
	        	});
	        }

	        if ($(".sunfw-scrollup").text().replace(/\s/g, "").length == 0) {
	        	$(".sunfw-scrollup").addClass('scrollup-icon');
	        }
			//scroll down
			$(".art-scroll-down").on('click', function(event) {
				if (this.hash !== "") {
					event.preventDefault();
					var hash = this.hash;
					$('html, body').animate({
						scrollTop: $(hash).offset().top
					}, 800, function(){
						window.location.hash = hash;
					});
				}
			});
		})(jQuery);

		//Offcanvas Menu

		(function($) {
			$('.offcanvas-content .navbar-header').remove();
			$('.offcanvas-content .sunfw-menu').removeClass('collapse');
			$('.offcanvas-content .sunfw-menu .sunfw-tpl-menu li').removeClass('sunfw-submenu-flipback');
			var iconCaret = $('.offcanvas-content .sunfw-menu span.caret');
		})(jQuery);
	},

	initOnLoad: function()
	{
		//console.log('initOnLoad');
	},

	stickyMenu: function (element) {
		var header       = '.sunfw-sticky';
		var stickyNavTop = jQuery(header).offset().top;

		var stickyNav = function () {

			var scrollTop    = jQuery(document).scrollTop();
			var placeholder = jQuery('.sunfw-sticky-placeholder')
			if (scrollTop > stickyNavTop) {
				jQuery(header).addClass('sunfw-sticky-open');
				placeholder.show();
			} else {
				jQuery(header).removeClass('sunfw-sticky-open');
				placeholder.hide();
			}

		};

		stickyNav();

		jQuery(window).scroll(function() {
			stickyNav();
		});
	},

	initTemplate: function(templateParams)
	{
		// Store template parameters
		_templateParams = templateParams;

		jQuery(document).ready(function ()
		{
			SunBlank.initOnDomReady();
			// Check width box layout
			if(jQuery('.sunfw-content.boxLayout').length > 0 && jQuery('.sunfw-sticky.sunfw-section')) {
				SunBlank.setWidtSectionMenu();
				jQuery( window ).resize(function() {
					SunBlank.setWidtSectionMenu();
				});
			}
		});

		jQuery(window).load(function ()
		{
			SunBlank.initOnLoad();

			// Check sticky
			if( jQuery('.sunfw-section').hasClass('sunfw-sticky')) {
				var stickyHeight = jQuery('.sunfw-sticky').outerHeight();
				jQuery('.sunfw-sticky').after('<div class="sunfw-sticky-placeholder" style="height:' + stickyHeight +  'px"></div>');
				SunBlank.stickyMenu();
			}
		});
	}
}

